def to_series(raw: str) -> dict:
    # raw는 Frankfurter /v1 응답 원본. rates의 각 날짜에서 KRW 값만 추출한다.
    d = json.loads(raw)
    return {date: v["KRW"] for date, v in d["rates"].items()}


def main():
    merged = {}
    for raw in (RAW_2022, RAW_2023, RAW_2024, RAW_2025):
        merged.update(to_series(raw))  # 경계 중복일은 자동으로 덮어써져 1개만 남음

    s = pd.Series(merged, name="Close")
    s.index = pd.to_datetime(s.index)
    s = s.sort_index()
    # 분석 기간을 2022-01-01 ~ 2025-12-31로 한정 (2021-12-31 경계값 제거)
    s = s.loc["2022-01-01":"2025-12-31"]

    df = s.to_frame()
    df.index.name = "Date"
    out = "data/usdkrw_2022_2025.csv"
    df.to_csv(out)
    print(f"저장: {out}")
    print(f"행 수: {len(df)}  기간: {df.index.min().date()} ~ {df.index.max().date()}")
    print(df.head(3))
    print(df.tail(3))


if __name__ == "__main__":
    main()
